import{_ as a,o,c as t,a3 as n}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Booking and paying","description":"","frontmatter":{},"headers":[],"relativePath":"user/client/booking.md","filePath":"user/client/booking.md"}'),i={name:"user/client/booking.md"};function r(s,e,h,c,l,d){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="booking-and-paying" tabindex="-1">Booking and paying <a class="header-anchor" href="#booking-and-paying" aria-label="Permalink to &quot;Booking and paying&quot;">​</a></h1><p>You need an account to book. Sign in with your phone number and the code you receive.</p><h2 id="booking" tabindex="-1">Booking <a class="header-anchor" href="#booking" aria-label="Permalink to &quot;Booking&quot;">​</a></h2><ol><li>Choose a service, a day and a time (or dates, for resorts).</li><li>The app shows a <strong>quote</strong>: the price, any discount and whether it is available.</li><li>Confirm and choose how to pay.</li></ol><p>You can only book a slot that is in the future, has space, and is not closed. You cannot book a center that has blocked you.</p><h2 id="paying" tabindex="-1">Paying <a class="header-anchor" href="#paying" aria-label="Permalink to &quot;Paying&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Online</strong></td><td>You pay through the payment provider. The booking stays <strong>pending</strong> until payment succeeds, then becomes <strong>confirmed</strong>.</td></tr><tr><td><strong>Cash on arrival</strong></td><td>Available only when the center allows it. The booking is confirmed immediately.</td></tr></tbody></table><p>If you do not pay online within the hold time, the booking is cancelled and the slot is released. If a payment still arrives after that, it is <strong>refunded automatically</strong>.</p><h2 id="one-checkout-one-center" tabindex="-1">One checkout, one center <a class="header-anchor" href="#one-checkout-one-center" aria-label="Permalink to &quot;One checkout, one center&quot;">​</a></h2><p>You can pay for several bookings together, but only from the <strong>same center</strong>.</p><h2 id="my-bookings" tabindex="-1">My bookings <a class="header-anchor" href="#my-bookings" aria-label="Permalink to &quot;My bookings&quot;">​</a></h2><p><strong>My bookings</strong> is one list of your reservations, packages and memberships, newest first. Unpaid packages and memberships are not listed.</p><p>Each reservation and each purchase has a 6-character <strong>code</strong> (for example <code>K7QX2M</code>). Show it at the center so staff can find your booking quickly. Bookings, packages and memberships also show a short summary of their purchase: code, status, total, discount, payment and the center&#39;s address and contact.</p><h2 id="cancelling" tabindex="-1">Cancelling <a class="header-anchor" href="#cancelling" aria-label="Permalink to &quot;Cancelling&quot;">​</a></h2><p>You can cancel until the cutoff (a number of hours before the start time).</p><ul><li>Online payments are <strong>refunded</strong>. If the refund cannot be made, the booking stays.</li><li>Cash or unpaid bookings have nothing to refund.</li><li>A session booked with a package is given back to the package.</li></ul><h2 id="changing-the-time" tabindex="-1">Changing the time <a class="header-anchor" href="#changing-the-time" aria-label="Permalink to &quot;Changing the time&quot;">​</a></h2><p>Ask the center to <strong>reschedule</strong>. The price must stay the same.</p>',18)])])}const p=a(i,[["render",r]]);export{u as __pageData,p as default};
